#include <memory>
#include <iostream>

struct Data { int val = 42; };

// BAD EXAMPLE: Transfers ownership to 'p', deletes resource on exit
void bad_print(std::auto_ptr<Data> p) {
    if (p.get()) {
        std::cout << "Printing: " << p->val << std::endl;
    }
} // p is destroyed here, deleting the Data object

int main() {
    std::auto_ptr<Data> p_owner(new Data);

    bad_print(p_owner); // p_owner is now NULL

    // The resource has already been deleted
    if (p_owner.get() == nullptr) {
        std::cout << "Resource unexpectedly deleted.\n";
    }
    // *p_owner; // FATAL runtime error (accessing deleted memory)
}
